ALTER POLICY payments_owner ON public.bill_payments USING (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.recurring_bills b WHERE b.id=bill_id AND b.user_id=auth.uid())) WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.recurring_bills b WHERE b.id=bill_id AND b.user_id=auth.uid()) AND (transaction_id IS NULL OR EXISTS(SELECT 1 FROM public.transactions t WHERE t.id=transaction_id AND t.user_id=auth.uid())));